import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestButton } from "../components/auditRequestModal";
import { trackEvent } from "../utils/analytics";

// ── Arrow icon
function ArrowIcon() {
  return (
    <svg className="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M5 12h14M13 5l7 7-7 7" />
    </svg>
  );
}

// ── Mono tags per service key
const svcTagsByKey: Record<string, string> = {
  cwv:                    "LCP · INP · CLS",
  designSystems:          "Figma · Tokens · React",
  accessibilityAudit:     "WCAG · Audit · Plan",
  performanceOptimization:"Load · Cache · Images",
};

export default function ServicesPage() {
  const { t } = useTranslation();
  const { language } = useI18next();

  // ── Translation data
  const displayLines = (t("servicesHub.displayLines", { returnObjects: true }) as string[]) || [];
  const servicesItems = (t("services.items", { returnObjects: true }) as Array<{
    key: string;
    title: string;
    desc: string;
    href: string;
  }>) || [];
  const deliverItems = (t("deliver.items", { returnObjects: true }) as Array<{
    title: string;
    desc: string;
  }>) || [];
  const processSteps = (t("process.steps", { returnObjects: true }) as Array<{
    title: string;
    desc: string;
  }>) || [];
  const heroPills = (t("servicesHub.heroPills", { returnObjects: true }) as string[]) || [];

  const portfolioHref = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";

  return (
    <Layout data={info}>
      <main>

        {/* ======================================================
            HERO
        ====================================================== */}
        <section className="pf-hero shell">
          <div className="pf-hero-grid">

            <div className="pf-hero-meta">
              <div className="eyebrow">§ 01 · {t("servicesHub.kicker")}</div>
              <div className="mono muted" style={{ marginTop: "12px" }}>
                {servicesItems.length} {t("servicesHub.countLabel")}
                {heroPills.map((pill) => (
                  <span key={pill}> · {pill}</span>
                ))}
              </div>
            </div>

            <h1
              className="display-xl pf-title"
              aria-label={t("servicesHub.h1") as string}
            >
              {displayLines.map((line, i) => (
                <span key={line} className="reveal-line">
                  <span>
                    {i === 1
                      ? <em className="italic">{line}</em>
                      : line}
                  </span>
                </span>
              ))}
            </h1>

            <p className="body-lg pf-intro reveal">{t("servicesHub.lede")}</p>

            <div className="reveal" style={{ display: "flex", gap: "12px", flexWrap: "wrap", paddingTop: "8px" }}>
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="services.hero.primary"
                className="btn btn-dark"
              >
                {t("contact.cta")}
                <ArrowIcon />
              </AuditRequestButton>
              <Link
                to={portfolioHref}
                className="btn btn-ghost"
              >
                {t("selectedProjects.labels.viewSelectedProjects")}
              </Link>
            </div>

          </div>
        </section>

        {/* ======================================================
            SERVICE CARDS — linkable offers
        ====================================================== */}
        <section className="services shell">
          <header className="sec-head">
            <div className="eyebrow">§ 02 · {t("servicesHub.listTitle")}</div>
            <h2 className="display-l reveal">{t("servicesHub.listTitle")}</h2>
            <p className="body-lg reveal">{t("servicesHub.listDesc")}</p>
          </header>

          <ol className="svc-list" data-stagger>
            {servicesItems.map((service, i) => (
              <li key={service.key} className="svc reveal" style={{ position: "relative" }}>
                {/* Invisible full-cover link for accessibility + click area */}
                <Link
                  to={service.href}
                  onClick={() =>
                    trackEvent("service_click", {
                      source: "services.list",
                      service_key: service.key,
                    })
                  }
                  aria-label={service.title}
                  style={{ position: "absolute", inset: 0, zIndex: 1 }}
                />
                <span className="num">{String(i + 1).padStart(2, "0")}</span>
                <h3 className="display-s">{service.title}</h3>
                <p className="body">{service.desc}</p>
                <div className="svc-tags mono">{svcTagsByKey[service.key] || ""}</div>
              </li>
            ))}
          </ol>
        </section>

        {/* ======================================================
            FULL CAPABILITIES — deliver.items
        ====================================================== */}
        <section className="who shell">
          <header className="sec-head">
            <div className="eyebrow">§ 03 · {t("deliver.title").split(" ").slice(0, 3).join(" ")}</div>
            <h2 className="display-l reveal">{t("deliver.title")}</h2>
          </header>

          <div className="who-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
            {deliverItems.map((item) => (
              <article key={item.title} className="who-card tilt reveal">
                <div className="tilt-inner">
                  <h3 className="display-s" style={{ fontSize: "clamp(18px, 1.6vw, 24px)" }}>
                    {item.title}
                  </h3>
                  <p className="body" style={{ marginTop: "16px", fontSize: "14px" }}>{item.desc}</p>
                </div>
              </article>
            ))}
          </div>
        </section>

        {/* ======================================================
            PROCESS
        ====================================================== */}
        <section id="process" className="process shell">
          <header className="sec-head">
            <div className="eyebrow">§ 04 · {t("process.title")}</div>
            <h2 className="display-l reveal">{t("process.title")}</h2>
          </header>
          <div className="process-grid">
            {processSteps.map((step, i) => (
              <div key={step.title} className="proc-step reveal">
                <div className="proc-num">{String(i + 1).padStart(2, "0")}</div>
                <h3 className="display-s">{step.title}</h3>
                <p className="body">{step.desc}</p>
              </div>
            ))}
          </div>
        </section>

        {/* ======================================================
            CTA
        ====================================================== */}
        <section className="portfolio-preview shell">
          <div
            className="portfolio-foot"
            style={{ paddingTop: "80px", borderTop: "1px solid var(--rule)" }}
          >
            <div>
              <p className="eyebrow">§ 05 · {t("selectedProjects.cta.title").split(" ").slice(0, 4).join(" ")}</p>
              <p className="body-lg" style={{ marginTop: "12px", maxWidth: "48ch" }}>
                {t("selectedProjects.cta.desc")}
              </p>
            </div>
            <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", alignSelf: "flex-start" }}>
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="services.cta.primary"
                className="btn btn-dark"
              >
                {t("selectedProjects.labels.requestAudit")}
                <ArrowIcon />
              </AuditRequestButton>
              <Link
                to={portfolioHref}
                className="btn btn-ghost"
              >
                {t("selectedProjects.labels.viewSelectedProjects")}
              </Link>
            </div>
          </div>
        </section>

      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/services/" : "/en/services/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/services/" },
    { hrefLang: "en", href: "https://riano.ca/en/services/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/services/" },
  ];

  return (
    <SEO
      data={info}
      titleKey="servicesHub.meta.title"
      descriptionKey="servicesHub.meta.description"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
